use hp_pcf::{dmx::Value,editor::{Category,Document}};use hp_gma::{AddonJson,GmaWriter,GmaSource,GmaArchive};
fn a(v:Vec<(&str,Value)>)->Vec<(String,Value)>{v.into_iter().map(|(k,v)|(k.into(),v)).collect()}
fn main()->Result<(),Box<dyn std::error::Error>>{let args:Vec<_>=std::env::args_os().collect();let out=std::path::Path::new(args.get(1).ok_or("output folder")?);let game=std::path::Path::new(args.get(2).ok_or("owned compiled game folder")?);let old=GmaArchive::open(out.join("hp_weighted117.gma"))?;let mut g=GmaWriter::new(AddonJson{title:"Owned weighted particle model sequences".into(),..Default::default()});for ext in ["mdl","vvd","dx90.vtx","dx80.vtx"]{let name=format!("models/hp_modelweight117/probe.{ext}");g.add(&name,GmaSource::Bytes(std::fs::read(game.join(&name))?)).unwrap();}for name in ["materials/hp_modelanim117/gray.vmt","materials/hp_modelanim117/white.vtf"]{g.add(name,GmaSource::Bytes(old.read(name)?.ok_or("owned model material")?)).unwrap();}g.write(&out.join("hp_weighted117.gma"))?;
let mut d=Document::new();for name in (1..=3).map(|i|format!("sequence{i}")).chain((0..32).map(|i|format!("weighted{i}"))){let id=d.create_system(&format!("hp_weighted117_{name}"))?;d.set_attrs(id,a(vec![("max_particles",Value::Int(1)),("radius",Value::Float(1.)),("material",Value::Str("hp_modelanim117/gray".into())),("bounding_box_min",Value::Vec3([0.;3])),("bounding_box_max",Value::Vec3([0.;3])),("sequence_number 1",Value::Int(if name.starts_with("sequence"){name[8..].parse()?}else{0}))]))?;d.add_operator_with_params(id,Category::Emitters,"emit_instantaneously",a(vec![("num_to_emit",Value::Int(1))]))?;d.add_operator_with_params(id,Category::Initializers,"Position Within Box Random",a(vec![("min",Value::Vec3([10.,0.,0.])),("max",Value::Vec3([10.,0.,0.]))]))?;d.add_operator_with_params(id,Category::Initializers,"Lifetime Random",a(vec![("lifetime_min",Value::Float(100.)),("lifetime_max",Value::Float(100.))]))?;d.add_operator_with_params(id,Category::Renderers,"Render models",a(vec![("sequence 0 model",Value::Str("hp_modelweight117/probe.mdl".into())),("animation rate",Value::Float(0.)),("activity override",Value::Str(if name.starts_with("weighted"){"ACT_IDLE"}else{""}.into()))]))?;}std::fs::write(out.join("hp_weighted117.pcf"),d.to_bytes()?)?;Ok(())}
